#include "rtos_static.hpp"
#include <assert.h>
using namespace rtos::static_storage;
int main(){size_t sum=7;assert(!checked_add(SIZE_MAX,1,sum)&&sum==7);assert(checked_add(3,4,sum)&&sum==7);uint32_t n=UINT32_MAX;saturate(n);assert(n==UINT32_MAX);Ring<int,2> q;int value=9;assert(q.pop(value)==Result::empty&&value==9);assert(q.push(1)==Result::ok&&q.push(2)==Result::ok&&q.push(3)==Result::full&&q.drops()==1);assert(*q.peek()==1);assert(q.pop(value)==Result::ok&&value==1);assert(q.push(4)==Result::ok);assert(q.pop(value)==Result::ok&&value==2);assert(q.pop(value)==Result::ok&&value==4);q.clear();assert(q.size()==0);Pool<2,16> pool;Token a,b,c;MutableBytes bytes;assert(pool.acquire(a,bytes)==Result::ok&&bytes.size==16);assert(pool.acquire(b,bytes)==Result::ok);assert(pool.acquire(c,bytes)==Result::full);assert(pool.release(a)==Result::ok&&pool.release(a)==Result::stale);assert(pool.acquire(c,bytes)==Result::ok&&c.generation!=a.generation);assert(pool.quarantine(c)==Result::quarantined&&pool.release(c)==Result::stale&&pool.conserved());assert(!(Bytes{nullptr,1}.valid()));}
